-- Demo catalog: fictional PKR prices and inventory; not purchasable.
-- Run after schema.sql in Supabase SQL Editor. Existing product IDs are preserved.
begin;

on conflict (id) do nothing;

commit;

-- Inspect the resulting demo catalog.
select id, data ->> 'name' as name, data -> 'variants' as variants
from public.products where id in ('demo-premium-almonds', 'demo-premium-cashews', 'demo-roasted-pistachios', 'demo-salted-pistachios', 'demo-premium-walnuts', 'demo-ajwa-dates', 'demo-mabroom-dates', 'demo-golden-raisins', 'demo-mixed-dry-fruits', 'demo-royal-gift-box')
order by id;
